package br.com.equilibra.creditcard.domain;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="statement_payments", uniqueConstraints=@UniqueConstraint(name="uq_payment_transaction", columnNames="financial_transaction_id")) public class StatementPayment{
 @Id @Column(length=36,nullable=false,updatable=false) private String id; @Column(name="owner_id",length=36,nullable=false,updatable=false) private String ownerId; @Column(name="statement_id",length=36,nullable=false,updatable=false) private String statementId; @Column(name="bank_account_id",length=36,nullable=false,updatable=false) private String bankAccountId; @Column(precision=19,scale=2,nullable=false) private BigDecimal amount; @Column(name="paid_at",nullable=false) private Instant paidAt; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private StatementPaymentStatus status=StatementPaymentStatus.ACTIVE; @Column(name="financial_transaction_id",length=36,nullable=false,updatable=false) private String financialTransactionId; @Column(name="idempotency_key",length=100) private String idempotencyKey; @Column(name="created_at",nullable=false,updatable=false) private Instant createdAt; @Version private Long version;
 protected StatementPayment(){} public StatementPayment(String owner,String statement,String account,BigDecimal amount,Instant paidAt,String tx,String key){id=UUID.randomUUID().toString();ownerId=owner;statementId=statement;bankAccountId=account;this.amount=amount.setScale(2);this.paidAt=paidAt;financialTransactionId=tx;idempotencyKey=key;} @PrePersist void create(){createdAt=Instant.now();}
 public String getId(){return id;} public String getOwnerId(){return ownerId;} public String getStatementId(){return statementId;} public String getBankAccountId(){return bankAccountId;} public BigDecimal getAmount(){return amount;} public Instant getPaidAt(){return paidAt;} public StatementPaymentStatus getStatus(){return status;} public String getFinancialTransactionId(){return financialTransactionId;} public String getIdempotencyKey(){return idempotencyKey;}
}
